-- 017: droga as it was from Classic to Velious (spawn points, groups and path grids from Quarm).
--
-- The dump has this zone in a later, revamped state. Generated by tools/npc_stats/gen_zone_from_quarm.py
-- (regenerate rather than edit): 465 spawn points, 18 spawn groups, 98 entries from the Quarm database,
-- ids + 1000000. NPCs are ours, matched by name; headings are Quarm's / 1.0198.
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): an_angry_goblin as npc_types 81464
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): a_goblin_bodyguard as npc_types 81131
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): a_goblin_soothsayer as npc_types 81132
-- Imported from Quarm (basic stats, loot table, faction list when we have none for the name): a_goblin_canyoneer as npc_types 81470
--
-- Our rows are kept in spawn2_before_era, spawngroup_before_era, spawnentry_before_era, grid_before_era and
-- grid_entries_before_era. To restore: delete the zone's rows with id >= 1000000 (spawn2, and spawngroup /
-- spawnentry by spawngroupID), delete its grid / grid_entries rows, and insert the *_before_era rows back.
-- Idempotent.

CREATE TABLE IF NOT EXISTS spawn2_before_era LIKE spawn2;
CREATE TABLE IF NOT EXISTS spawngroup_before_era LIKE spawngroup;
CREATE TABLE IF NOT EXISTS spawnentry_before_era LIKE spawnentry;
CREATE TABLE IF NOT EXISTS grid_before_era LIKE grid;
CREATE TABLE IF NOT EXISTS grid_entries_before_era LIKE grid_entries;
CREATE TEMPORARY TABLE era_groups AS SELECT DISTINCT spawngroupID AS id FROM spawn2 WHERE zone = 'droga' AND id < 1000000
  AND spawngroupID NOT IN (SELECT spawngroupID FROM spawn2 WHERE zone <> 'droga');
DELETE FROM spawnentry WHERE spawngroupID IN (SELECT id FROM era_groups);
DELETE FROM spawngroup WHERE id IN (SELECT id FROM era_groups);
DELETE FROM spawn2 WHERE zone = 'droga' AND id < 1000000;
DROP TEMPORARY TABLE era_groups;
DELETE FROM grid_entries WHERE zoneid = 81;
DELETE FROM grid WHERE zoneid = 81;








